// Loads public/data/bass2.json and audit.json once, for every view that needs them (the audit bar
// on every view, SUMMARIZE). Both files are generated by npm run data:bass2, never hand-edited.
import { useSyncExternalStore } from 'react'
import type { AuditFile, Bass2File } from './audit'

export type AuditData =
  | { status: 'loading' }
  | { status: 'error'; message: string }
  | { status: 'ready'; bass2: Bass2File; audit: AuditFile }

let state: AuditData = { status: 'loading' }
let started = false
const listeners = new Set<() => void>()

async function fetchJson<T>(path: string): Promise<T> {
  const response = await fetch(`${import.meta.env.BASE_URL}${path}`)
  if (!response.ok) throw new Error(`${path}: ${response.status} ${response.statusText}`)
  return (await response.json()) as T
}

function start() {
  if (started) return
  started = true
  Promise.all([fetchJson<Bass2File>('data/bass2.json'), fetchJson<AuditFile>('data/audit.json')])
    .then(([bass2, audit]) => {
      state = { status: 'ready', bass2, audit }
    })
    .catch((error: unknown) => {
      state = { status: 'error', message: error instanceof Error ? error.message : String(error) }
    })
    .finally(() => {
      for (const listener of listeners) listener()
    })
}

function subscribe(listener: () => void) {
  listeners.add(listener)
  start()
  return () => {
    listeners.delete(listener)
  }
}

/** The BASS-II rows and audit summary, or 'loading' until both files arrive. */
export function useAuditData(): AuditData {
  return useSyncExternalStore(subscribe, () => state)
}
